// Pagination of /execute. 250 deterministic rows are generated by a recursive query on the read-only SQLite
// connection, so no fixture data is needed or touched.
const { test, expect } = require('../fixtures/api');

const connection_name = 'test-payroll';
const sql = 'WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM s WHERE n<250) SELECT n FROM s';
const page_size = 100;

const pages = [
  { pageNumber: 1, rows: 100, first: 1, last: 100, has_more: true },
  { pageNumber: 2, rows: 100, first: 101, last: 200, has_more: true },
  { pageNumber: 3, rows: 50, first: 201, last: 250, has_more: false }, // last, partial page
  { pageNumber: 4, rows: 0, has_more: false }, // beyond the end
];
for (const { pageNumber, rows, first, last, has_more } of pages) {
  test(`page ${pageNumber} returns ${rows} rows${rows ? ` (${first}..${last})` : ''}, has_more=${has_more}`, async ({ datapilot }) => {
    const response = await datapilot.execute({ connection_name, sql, page: pageNumber, page_size });

    expect(response.status()).toBe(200);
    const body = await response.json();
    expect(body.status, body.error).toBe('success');
    expect(body.row_count).toBe(rows);
    expect(body.data).toHaveLength(rows);
    if (rows) {
      expect(body.data[0].n).toBe(first);
      expect(body.data[body.data.length - 1].n).toBe(last);
    }
    expect(body.has_more).toBe(has_more);
  });
}

test('page 1 with include_total also reports the full result size', async ({ datapilot }) => {
  const body = await (await datapilot.execute({ connection_name, sql, page: 1, page_size, include_total: true })).json();

  expect(body).toMatchObject({ row_count: 100, has_more: true, total_row_count: 250 });
});

test('without a page parameter the whole result is returned', async ({ datapilot }) => {
  const response = await datapilot.execute({ connection_name, sql });

  expect(response.status()).toBe(200);
  const body = await response.json();
  expect(body.row_count).toBe(250);
  expect(body.data).toHaveLength(250);
  expect(body.has_more).toBe(false);
});

test('a page_size larger than the result returns every row and has_more=false', async ({ datapilot }) => {
  const body = await (await datapilot.execute({ connection_name, sql, page: 1, page_size: 1000 })).json();

  expect(body.row_count).toBe(250);
  expect(body.has_more).toBe(false);
});

test('count for a paged query reports the full result size', async ({ datapilot }) => {
  const paged = await (await datapilot.execute({ connection_name, sql, page: 1, page_size })).json();

  const response = await datapilot.count({ query_log_id: paged.query_log_id, connection_name, sql });

  expect(response.status()).toBe(200);
  expect((await response.json()).total_row_count).toBe(250);
});

test.fail('KNOWN DEFECT: a non-numeric page is a 4xx and does not leak the Python error', async ({ datapilot }) => {
  const response = await datapilot.execute({ connection_name, sql, page: 'x', page_size }); // currently 200 "failure" with the raw error

  expect(response.status()).toBeGreaterThanOrEqual(400);
  expect(response.status()).toBeLessThan(500);
  expect(await response.text()).not.toContain('not supported between');
});
